  cfUpDownPct: () => quickUpDown(true),
  cfWeekend: () => quickWeekend(),
  selectAllSmart: () => smartSelectAll(),
  selectRegion: () => { const rg = currentRegion(active.r, active.c); selectRange(rg, 'cells', { r: active.r, c: active.c }); },
  newWorkbook: () => newWorkbook(),
  nameManager, defineName, useInFormula: pasteNameDialog, pasteName: pasteNameDialog, createNamesFromSel,

  toggleFilter,
  advancedFilter: advancedFilterDialog,
  protectWorkbook: () => protectWorkbookDialog(),
  fileInfo: () => openBackstage('info'),
  insertIcons: () => { insertIconsDialog(); },
  clearFilter: () => {
    const key = filterKeyHere();
    const f = key === null ? null : getFilter(key);
    if (!f && advFilterState?.si === si) {
      // 고급 필터(현재 위치)로 숨긴 행을 모두 표시
      const hr = { ...(sheet().hiddenRows ?? {}) };
      for (let r = advFilterState.r1; r <= advFilterState.r2; r++) delete hr[r];
      wb.transact(() => wb.setSheetProp(si, 'hiddenRows', hr), meta());
      advFilterState = null;
      gv.layout();
      setMode();
      return;
    }
    if (!f) return;
    wb.transact(() => putFilter(key, { ...f, criteria: {}, hidden: {}, sort: undefined }), meta());
    gv.layout();
    setMode();
  },
  reapplyFilter: () => {
    const key = filterKeyHere();
    const f = key === null ? null : getFilter(key);
    if (!f || !canRecomputeFilter(f)) return;
    wb.transact(() => putFilter(key, recomputeFilter(f, key)), meta());
    gv.layout();
    setMode();
  },
